#!/bin/bash
input=$(cat); eval "$(echo "$input" | jq -r '@sh "model=\(.model.display_name // "?") effort=\(.effort.level // "") cwd=\(.workspace.current_dir // .cwd) wt=\(.worktree.name // .workspace.git_worktree // "") five=\(.rate_limits.five_hour.used_percentage // "") reset=\(.rate_limits.five_hour.resets_at // "")"')"; p(){ printf "\033[38;5;%sm%s\033[0m" "$1" "$2"; }; sep="  $(p 240 '│')  "; br=$(git --no-optional-locks -C "$cwd" symbolic-ref --short HEAD 2>/dev/null || git --no-optional-locks -C "$cwd" rev-parse --short HEAD 2>/dev/null); l1="$(p 33 "📁 Project: $(basename "$cwd")")"; [ -n "$br" ] && l1="$l1$sep$(p 35 "Branch: $br")"; [ -n "$wt" ] && l1="$l1$sep$(p 208 "Worktree: $wt")"; l2="$(p 141 "Model: $model")"; [ -n "$effort" ] && l2="$l2 $(p 176 "($effort)")"; [ -n "$five" ] && l2="$l2$sep$(p 220 "Usage: $(printf %.0f "$(echo "100-$five" | bc -l)")% left (5h)")"; [ -n "$reset" ] && l2="$l2$sep$(p 214 "Resets: $(date -r "$reset" +%-I:%M%p | tr '[:upper:]' '[:lower:]')")"; printf '%s\n%s' "$l1" "$l2"
